import 'package:flutter/material.dart';import '../../core/theme/app_theme.dart';
class PageHeader extends StatelessWidget{const PageHeader(this.title,{super.key,this.subtitle});final String title;final String? subtitle;@override Widget build(BuildContext context)=>Padding(padding:const EdgeInsets.only(bottom:18),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(title,style:Theme.of(context).textTheme.headlineLarge),if(subtitle!=null)...[const SizedBox(height:6),Text(subtitle!,style:Theme.of(context).textTheme.bodyMedium)]]));}
class DisclaimerCard extends StatelessWidget{const DisclaimerCard({super.key});@override Widget build(BuildContext context)=>Container(padding:const EdgeInsets.all(13),decoration:BoxDecoration(color:const Color(0xFFFFF3DD),borderRadius:BorderRadius.circular(14)),child:const Text('Astrology is for entertainment and self-reflection, not factual prediction or professional advice.',style:TextStyle(fontSize:11,height:1.5,color:AppTheme.muted)));}
class InfoCard extends StatelessWidget{const InfoCard(this.text,{super.key});final String text;@override Widget build(BuildContext context)=>Container(padding:const EdgeInsets.all(15),decoration:BoxDecoration(color:AppTheme.secondary,borderRadius:BorderRadius.circular(15)),child:Text(text,style:const TextStyle(color:AppTheme.muted,height:1.5)));}
